fpath="ss_ge.h5"
# inspect structure
import h5py
with h5py.File(fpath,'r') as f:
    def visit(name,obj):
        print(name, type(obj).__name__, obj.shape if hasattr(obj,'shape') else '', obj.dtype if hasattr(obj,'dtype') else '')
