            # print small dataset
            if obj.size<20:
                try:
                    print("  data:", obj[()])
                except: pass
    f.visititems(visit)
    print("--- root attrs ---")
    for k,v in f.attrs.items():
        print(k, repr(v)[:1000])
PY

